/// 🧭️ Paid scalar positions over borrowed relational rows.
struct ModelRows<'a>{
 table:&'a semio_framework_os_kernel::sqlite_snapshot::SqliteTable,
 columns:&'static[FloatColumn],indices:Vec<usize>,used:Vec<u8>,remaining:usize,
}
/// 🚫️ Reports an authored Model relationship refusal.
fn model_invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
/// ⏱️ Checks each Model reconstruction frontier.
fn model_checkpoint(control:&mut SqliteSnapshotControl<'_>,completed:usize,total:usize)->Result<(),ValueError>{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,total)}
impl<'a> ModelRows<'a>{
 fn new(db:&'a SqliteDatabase,name:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{
  let table=db.table(name)?;let count=table.rows.len();control.check_rows(count)?;model_checkpoint(control,0,count)?;
  let mut indices=semio_framework_os_kernel::sqlite_snapshot::transfer::reserve(count,control)?;let mut used=semio_framework_os_kernel::sqlite_snapshot::transfer::reserve(count,control)?;
  for(index,row)in table.rows.iter().enumerate(){identity(SqliteRow::new(row,float_columns(name))?,columns)?;indices.push(index);used.push(0);model_checkpoint(control,index+1,count)?;}
  semio_framework_os_kernel::sqlite_snapshot::transfer::heap_sort(&mut indices,SqliteSnapshotPhase::ReconstructSnapshot,control,|a,b,_|Ok(table.rows[*a].rowid.cmp(&table.rows[*b].rowid)))?;
  for(index,pair)in indices.windows(2).enumerate(){if table.rows[pair[0]].rowid==table.rows[pair[1]].rowid{return Err(model_invalid(match name{"semio_model_property_set"=>"invalid Semio model property-set owner or identity","semio_model_property"=>"invalid Semio model property owner or identity","semio_model_relation"=>"invalid Semio model relation owner or identity",_=>"duplicate Semio model row identity"}));}model_checkpoint(control,index+1,count)?;}
  Ok(Self{table,columns:float_columns(name),indices,used,remaining:count})
 }
 fn row(&self,index:usize)->Result<SqliteRow<'a>,ValueError>{SqliteRow::new(&self.table.rows[index],self.columns)}
 fn position(&self,id:i64,control:&mut SqliteSnapshotControl<'_>)->Result<Option<usize>,ValueError>{
  let mut lo=0;let mut hi=self.indices.len();while lo<hi{model_checkpoint(control,lo,hi)?;let mid=lo+(hi-lo)/2;let index=self.indices[mid];match self.table.rows[index].rowid.cmp(&id){std::cmp::Ordering::Less=>lo=mid+1,std::cmp::Ordering::Greater=>hi=mid,std::cmp::Ordering::Equal=>return Ok(Some(index))}}Ok(None)
 }
 fn get(&self,id:i64,control:&mut SqliteSnapshotControl<'_>)->Result<Option<SqliteRow<'a>>,ValueError>{self.position(id,control)?.map(|index|self.row(index)).transpose()}
 fn take(&mut self,id:i64,control:&mut SqliteSnapshotControl<'_>)->Result<Option<SqliteRow<'a>>,ValueError>{
  let Some(index)=self.position(id,control)?else{return Ok(None)};if self.used[index]!=0{return Ok(None)}self.used[index]=1;self.remaining-=1;self.row(index).map(Some)
 }
}
/// 🪪️ Validates literal identities through paid positions and cancellable byte comparisons.
fn model_unique_text(rows:&ModelRows<'_>,column:usize,message:&str,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 let mut indices=semio_framework_os_kernel::sqlite_snapshot::transfer::reserve(rows.indices.len(),control)?;
 for &index in &rows.indices{rows.row(index)?.text(column)?;indices.push(index);model_checkpoint(control,indices.len(),rows.indices.len())?;}
 semio_framework_os_kernel::sqlite_snapshot::transfer::heap_sort(&mut indices,SqliteSnapshotPhase::ReconstructSnapshot,control,|a,b,c|semio_framework_os_kernel::sqlite_snapshot::transfer::compare_text(rows.row(*a)?.text(column)?,rows.row(*b)?.text(column)?,SqliteSnapshotPhase::ReconstructSnapshot,c))?;
 for pair in indices.windows(2){if semio_framework_os_kernel::sqlite_snapshot::transfer::compare_text(rows.row(pair[0])?.text(column)?,rows.row(pair[1])?.text(column)?,SqliteSnapshotPhase::ReconstructSnapshot,control)?.is_eq(){return Err(model_invalid(message));}}Ok(())
}
/// 🔢️ Orders a paid partition by its exact contiguous authored ordinals.
fn ordered(mut indices:Vec<usize>,rows:&ModelRows<'_>,column:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<usize>,ValueError>{
 semio_framework_os_kernel::sqlite_snapshot::transfer::heap_sort(&mut indices,SqliteSnapshotPhase::ReconstructSnapshot,control,|a,b,_|Ok(rows.row(*a)?.integer(column)?.cmp(&rows.row(*b)?.integer(column)?)))?;
 for(ordinal,&index)in indices.iter().enumerate(){if rows.row(index)?.integer(column)?!=number(ordinal)?{return Err(model_invalid("Semio model ordinals must be contiguous"));}model_checkpoint(control,ordinal+1,indices.len())?;}Ok(indices)
}
/// 👪️ Groups paid positions by owner and contiguous per-owner ordinal.
fn model_groups(rows:&ModelRows<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<usize>,ValueError>{
 let mut indices=semio_framework_os_kernel::sqlite_snapshot::transfer::reserve(rows.indices.len(),control)?;
 for &index in &rows.indices{indices.push(index);model_checkpoint(control,indices.len(),rows.indices.len())?;}
 semio_framework_os_kernel::sqlite_snapshot::transfer::heap_sort(&mut indices,SqliteSnapshotPhase::ReconstructSnapshot,control,|a,b,_|{let a=rows.row(*a)?;let b=rows.row(*b)?;Ok(a.integer(1)?.cmp(&b.integer(1)?).then(a.integer(2)?.cmp(&b.integer(2)?)))})?;
 let mut previous=None;let mut ordinal=0;for(index,&position)in indices.iter().enumerate(){let row=rows.row(position)?;let owner=row.integer(1)?;if previous!=Some(owner){previous=Some(owner);ordinal=0;}if row.integer(2)?!=number(ordinal)?{return Err(model_invalid("Semio model ordinals must be contiguous"));}ordinal+=1;model_checkpoint(control,index+1,indices.len())?;}Ok(indices)
}
/// 🔎️ Finds one owner's exact range without heap ownership.
fn model_group_range(rows:&ModelRows<'_>,indices:&[usize],owner:i64,control:&mut SqliteSnapshotControl<'_>)->Result<std::ops::Range<usize>,ValueError>{
 let mut lo=0;let mut hi=indices.len();while lo<hi{model_checkpoint(control,lo,hi)?;let mid=lo+(hi-lo)/2;if rows.row(indices[mid])?.integer(1)?<owner{lo=mid+1}else{hi=mid}}let start=lo;hi=indices.len();while lo<hi{model_checkpoint(control,lo,hi)?;let mid=lo+(hi-lo)/2;if rows.row(indices[mid])?.integer(1)?<=owner{lo=mid+1}else{hi=mid}}Ok(start..lo)
}
/// ♻️ Closes cycle marks in two paid scalar walks.
fn cycles(parents:&mut[(Option<usize>,u8)],control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{
 for root in 0..parents.len(){let mut current=Some(root);while let Some(index)=current{model_checkpoint(control,index,parents.len())?;match parents[index].1{2=>break,1=>return Err(model_invalid("cyclic Semio model spatial hierarchy")),_=>{parents[index].1=1;current=parents[index].0;}}}let mut current=Some(root);while let Some(index)=current{model_checkpoint(control,index,parents.len())?;if parents[index].1!=1{break}parents[index].1=2;current=parents[index].0;}}Ok(())
}
